COURSE = dict(id="industry-analysis", level="practitioner", title="Industry and sector analysis", sec="stocks", track="research", topic="Industry analysis", tag="IND",
  blurb="Judge an industry before a company: demand, competition, cycles, moats and regulation.",
  hook="A good company in a bad industry struggles. Learn to read the industry first.",
  fun=["An industry's structure can matter more than any single company in it.", "Some industries rise and fall with the economy, while others grow steadily."],
  traps=["Judging a company without looking at its industry.", "Treating a cyclical peak as the new normal.", "Ignoring regulation and policy changes."],
  lessons=[
  dict(title="Size and growth", intro="Start with how big the industry is and how fast it can grow.", concepts=[
    ("Total addressable market", "Total addressable market is the full amount of sales a product could earn if it reached every possible buyer.", "A start-up estimates how many Indian households could buy its water purifier."),
    ("Market share", "Market share is the portion of an industry's sales that one company holds.", "One brand sells 30 of every 100 scooters bought."),
    ("Penetration", "Penetration is the share of possible customers who already use a product.", "Only a small fraction of households own an air conditioner."),
    ("Demand driver", "A demand driver is a factor that makes customers buy more, such as rising incomes or new rules.", "Rising incomes lead more families to buy cars.")],
    client=("“This sector is booming. Will every company in it do well?”", "A client chasing a popular sector."), talk="“A growing industry lifts many companies, but not all. Margins, competition and balance sheets decide who actually benefits.”", remember=["Size shows the room to grow.", "Penetration shows how much is left.", "Growth does not guarantee profit."]),
  dict(title="Competition", intro="Profit goes to the companies that rivals cannot easily copy.", concepts=[
    ("Porter's five forces", "Porter's five forces is a framework that judges industry competition by looking at rivals, new entrants, substitutes, buyers and suppliers.", "An analyst checks how easily new firms can enter and how much power customers hold."),
    ("Barriers to entry", "Barriers to entry are costs or rules that make it hard for new firms to join an industry.", "A telecom start-up needs licences and huge spending on airwaves."),
    ("Economic moat", "An economic moat is a lasting advantage that protects a company's profits from rivals.", "A well-loved brand keeps customers even when cheaper options appear."),
    ("Pricing power", "Pricing power is the ability to raise prices without losing many customers.", "A toothpaste maker raises prices slightly and sales barely change.")],
    client=("“Why does this company earn more than its rivals?”", "A client comparing two firms."), talk="“Look for a lasting edge such as brand, scale or a cost advantage. If rivals can copy it easily, the high profit may not last.”", remember=["Entry barriers protect profits.", "A moat must be durable.", "Pricing power shows strength."]),
  dict(title="Cycles", intro="Some industries move with the economy. Know where you are in the cycle.", concepts=[
    ("Cyclical industry", "A cyclical industry is one whose sales and profits rise and fall with the economy.", "Steel and cement firms earn much more in boom years than in slowdowns."),
    ("Defensive industry", "A defensive industry is one whose demand stays steady in good and bad times.", "People keep buying soap and medicines even when money is tight."),
    ("Capacity utilisation", "Capacity utilisation is the share of a plant's possible output that is actually produced.", "A factory that could make 100 units is running at 78."),
    ("Commodity price cycle", "A commodity price cycle is the repeated rise and fall of raw material prices that drives the profits of related industries.", "Metal prices climb for two years, then fall for two.")],
    client=("“This company's profit doubled. Is it the new normal?”", "A client extrapolating a peak."), talk="“In a cyclical business, peak profits often fade. Check where we are in the cycle before paying a high price.”", remember=["Cyclicals follow the economy.", "Defensives hold steady.", "Do not extrapolate peaks."]),
  dict(title="Policy and regulation", intro="Rules, taxes and incentives can change an industry's profits overnight.", concepts=[
    ("Regulator", "A regulator is a government body that makes and enforces the rules for an industry.", "SEBI oversees securities markets and RBI oversees banks."),
    ("Import duty", "Import duty is a tax on imported goods that can protect local producers and raise prices.", "A higher tax on foreign steel makes it costlier than local steel."),
    ("Production-linked incentive", "A production-linked incentive is a government reward paid to firms based on how much they make in the country.", "A phone maker receives support for each additional unit it assembles locally."),
    ("Policy risk", "Policy risk is the chance that a change in rules, taxes or subsidies hurts an industry.", "A new price cap suddenly cuts the earnings of drug makers.")],
    client=("“The government announced support for this sector. Should I buy?”", "A client reacting to a headline."), talk="“Policy can help, but benefits take time and may go to only a few firms. We check who qualifies and how much it changes earnings.”", remember=["Rules shape returns.", "Incentives favour some firms.", "Policy can reverse."]),
  dict(title="Putting it together", intro="Combine size, competition, cycles and policy into one view.", concepts=[
    ("Value chain", "A value chain is the series of steps from raw material to final customer, where each step adds value and takes a share of profit.", "In footwear, design, manufacturing, branding and retail each earn a different margin."),
    ("Industry life cycle", "The industry life cycle is the pattern of birth, growth, maturity and decline that industries pass through.", "Mobile phones moved from rapid growth to a mature, replacement-driven market."),
    ("Peer comparison", "Peer comparison judges a company against similar firms on growth, margins and returns.", "A bank's loan growth is set beside that of other private banks."),
    ("Disruption", "Disruption is when new technology or business models upend how an industry earns its profit.", "Online payment apps changed how people pay across shops and banks.")],
    client=("“What should I check before picking a company in a sector?”", "A client starting research."), talk="“Start with the industry: how big, how fast, how competitive and how cyclical. Then pick the company with the strongest position in it.”", remember=["Industry first, company next.", "Compare with peers.", "Watch for disruption."]),
  ])
